import React, { useState, useEffect } from "react";
import { listenPrograms, addProgram, updateProgram, deleteProgram, submitProgram, submitSubProgram, DEFAULT_PROGRAMS, PROGRAM_CATEGORIES } from "../services/programService";
import { listenActivities } from "../services/activityService";
import { listenBudgetEntries } from "../services/budgetService";
import { listenSettings } from "../services/settingsService";
import { addAudit, AUDIT_ACTIONS } from "../services/auditService";
import RichTextEditor, { renderHtml } from "../components/RichTextEditor";
import { notifySubmission } from "../services/notificationService";
import { batchWrite } from "../firebase/firestore";
import ImportBudgetModal from "../components/ImportBudgetModal";

const STATUS_BADGE = {
  draft:     { label: "Draft",            color: "#2563eb", bg: "#eff6ff" },
  submitted: { label: "Pending approval", color: "#d97706", bg: "#fff8e1" },
  approved:  { label: "Approved (Locked)", color: "#2d7a4f", bg: "#f0f7f3" },
};

const PROGRAM_COLORS = ["#2d7a4f", "#2563eb", "#9333ea", "#d97706", "#0891b2", "#c0392b", "#059669", "#7c3aed", "#db2777"];

const EXPENSE_TYPES = [
  "Food and drinks", "Venue / Room Hire", "Transport", "Facilitators",
  "Equipment", "Materials", "Internet/Supplies", "Bank charges", "Other",
];

function fmt(n)    { return (n || 0).toLocaleString(); }
function fmtUSD(n) { return `$${(n || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`; }

function emptyItem(rate) {
  return { id: Date.now().toString() + Math.random(), description: "", note: "", unitCost: 0, quantity: 1, expenseType: "Food and drinks", exchangeRate: rate };
}

function emptySubProgram() {
  return { id: Date.now().toString() + Math.random(), name: "", description: "", budgetItems: [] };
}

function emptyProgram(rate) {
  return { name: "", category: "Content Creation", description: "", plannedSessions: 1, color: PROGRAM_COLORS[0], exchangeRate: rate, budgetItems: [], subPrograms: [] };
}

function computeTotal(items) {
  return items.reduce((s, item) => s + (Number(item.unitCost) || 0) * (Number(item.quantity) || 1), 0);
}

// Once a program defines sub-programs (sessions), that list is the source of
// truth for "how many sessions" — the old manually-typed plannedSessions
// number is only used as a fallback for programs that don't use sub-programs.
function effectivePlannedSessions(p) {
  return (p.subPrograms && p.subPrograms.length > 0) ? p.subPrograms.length : (p.plannedSessions || 1);
}

// A program "has a budget" if it has program-level line items OR any
// sub-program (session) has line items of its own — submission, the
// "View budget" toggle, etc. shouldn't only look at the program-level list.
function hasBudget(p) {
  return (p.budgetItems?.length > 0) || (p.subPrograms || []).some(sp => (sp.budgetItems || []).length > 0);
}

export default function Programs({ profile, grantId, currentGrant }) {
  const [programs,    setPrograms]    = useState([]);
  const [activities,  setActivities]  = useState([]);
  const [budgetEntries, setBudgetEntries] = useState([]);
  const [settings,    setSettings]    = useState(null);
  const [showForm,    setShowForm]    = useState(false);
  const [editId,      setEditId]      = useState(null);
  const [form,        setForm]        = useState(emptyProgram(0.000438));
  const [expanded,    setExpanded]    = useState(null); // program id showing budget detail
  const [toast,       setToast]       = useState("");
  const [bannerDismissed, setBannerDismissed] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const canEdit = ["admin", "coordinator"].includes(profile?.role);
  // The importer writes programs, settings.personnel, and budget entries in one action —
  // each has a different Firestore role boundary (coordinator/finance/admin respectively),
  // so the only role that passes every one of them is admin. Keep this admin-only.
  const canImport = profile?.role === "admin";

  useEffect(() => {
    const u1 = listenPrograms(setPrograms);
    const u2 = listenActivities(setActivities);
    const u3 = listenSettings(setSettings);
    const u4 = listenBudgetEntries(setBudgetEntries);
    return () => { u1(); u2(); u3(); u4(); };
  }, []);

  const rate = Number(currentGrant?.conversionRate || settings?.grant?.conversionRate || 0.000438);

  const showToast = (msg) => { setToast(msg); setTimeout(() => setToast(""), 3000); };
  const setF = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const openCreate = () => { setForm(emptyProgram(rate)); setEditId(null); setShowForm(true); };
  const openEdit   = (p) => {
    setForm({
      name: p.name, category: p.category, description: p.description || "",
      plannedSessions: p.plannedSessions || 1, color: p.color || PROGRAM_COLORS[0],
      exchangeRate: p.exchangeRate || rate,
      budgetItems: (p.budgetItems || []).map(it => ({ ...it })),
      subPrograms: (p.subPrograms || []).map(sp => ({ ...sp, budgetItems: (sp.budgetItems || []).map(it => ({ ...it })) })),
    });
    setEditId(p.id); setShowForm(true);
  };

  // Budget item handlers
  const addItem    = () => setF("budgetItems", [...form.budgetItems, emptyItem(form.exchangeRate || rate)]);
  const removeItem = (i) => setF("budgetItems", form.budgetItems.filter((_, j) => j !== i));
  const setItem    = (i, k, v) => setF("budgetItems", form.budgetItems.map((it, j) => j === i ? { ...it, [k]: v } : it));

  // Sub-program handlers
  const addSubProgram    = () => setF("subPrograms", [...(form.subPrograms || []), emptySubProgram()]);
  const removeSubProgram = (si) => setF("subPrograms", form.subPrograms.filter((_, j) => j !== si));
  const setSubP          = (si, k, v) => setF("subPrograms", form.subPrograms.map((sp, j) => j === si ? { ...sp, [k]: v } : sp));
  const addSubItem       = (si) => setSubP(si, "budgetItems", [...(form.subPrograms[si].budgetItems || []), emptyItem(form.exchangeRate || rate)]);
  const removeSubItem    = (si, ii) => setSubP(si, "budgetItems", form.subPrograms[si].budgetItems.filter((_, j) => j !== ii));
  const setSubItem       = (si, ii, k, v) => setSubP(si, "budgetItems", form.subPrograms[si].budgetItems.map((it, j) => j === ii ? { ...it, [k]: v } : it));

  const save = async () => {
    if (!form.name.trim()) { alert("Program name is required."); return; }
    const subTotal = (form.subPrograms || []).reduce((s, sp) => s + computeTotal(sp.budgetItems || []), 0);
    const plannedBudget = computeTotal(form.budgetItems) + subTotal;
    const data = { ...form, plannedBudget, grantId: grantId || "" };
    if (!editId) {
      const id = await addProgram(data);
      await addAudit(profile, AUDIT_ACTIONS.CREATE, "programs", { targetId: id, recordTitle: form.name });
      showToast("Program created.");
    } else {
      await updateProgram(editId, data);
      await addAudit(profile, AUDIT_ACTIONS.UPDATE, "programs", { targetId: editId, recordTitle: form.name });
      showToast("Program updated.");
    }
    setShowForm(false);
  };

  const assignUnassigned = async () => {
    if (!grantId) return;
    const unassigned = programs.filter(p => !p.grantId);
    if (!unassigned.length) return;
    if (!window.confirm(`Assign ${unassigned.length} unassigned programs to this grant?`)) return;
    await batchWrite(unassigned.map(p => ({ type: "update", path: "programs", id: p.id, data: { grantId } })));
    setBannerDismissed(true);
    showToast(`${unassigned.length} programs assigned to grant.`);
  };

  const del = async (p) => {
    if (!window.confirm(`Delete program "${p.name}"? Activities linked to it will remain.`)) return;
    await deleteProgram(p.id);
    await addAudit(profile, AUDIT_ACTIONS.DELETE, "programs", { targetId: p.id, recordTitle: p.name });
    showToast("Program deleted.");
  };

  const submit = async (p) => {
    if (!hasBudget(p)) { alert("Add at least one budget item (or sub-program session budget) before submitting."); return; }
    if (!window.confirm(`Submit "${p.name}" for approval? You will not be able to edit it until it is reviewed.`)) return;
    await submitProgram(p.id, profile?.name || "");
    await addAudit(profile, AUDIT_ACTIONS.SUBMIT, "programs", { targetId: p.id, recordTitle: p.name });
    notifySubmission({ submitterName: profile?.name || "A coordinator", itemType: "Program", itemTitle: p.name, itemId: p.id }).catch(() => {});
    showToast(`"${p.name}" submitted for approval.`);
  };

  const submitSession = async (p, sp) => {
    if (!(sp.budgetItems || []).length) { alert("Add at least one budget item to this session before submitting."); return; }
    if (!window.confirm(`Submit session "${sp.name || "Untitled session"}" for approval?`)) return;
    await submitSubProgram(p.id, sp.id, profile?.name || "");
    await addAudit(profile, AUDIT_ACTIONS.SUBMIT, "programs", { targetId: p.id, recordTitle: `${p.name} — ${sp.name || "session"}` });
    notifySubmission({ submitterName: profile?.name || "A coordinator", itemType: "Program session", itemTitle: `${p.name} — ${sp.name || "session"}`, itemId: p.id }).catch(() => {});
    showToast(`Session "${sp.name || "session"}" submitted for approval.`);
  };

  const isAdmin = profile?.role === "admin";
  const isDraft = (p) => !p.status || p.status === "draft";
  const canEditProgram = (p) => isAdmin || (canEdit && isDraft(p));

  const statsFor = (pid) => {
    const acts = activities.filter(a => a.programId === pid);
    return {
      sessions:     acts.length,
      participants: acts.reduce((s, a) => s + (a.participants || 0), 0),
      women:        acts.reduce((s, a) => s + (a.women || 0), 0),
      newEditors:   acts.reduce((s, a) => s + (a.newEditors || 0), 0),
    };
  };

  const seedDefaults = async () => {
    if (!window.confirm("Add the 9 default program areas? Existing programs will not be affected.")) return;
    for (const p of DEFAULT_PROGRAMS) await addProgram({ ...p, exchangeRate: rate, budgetItems: [], grantId: grantId || "" });
    showToast("Default programs added.");
  };

  const unassignedCount = grantId ? programs.filter(p => !p.grantId).length : 0;
  const visiblePrograms = grantId ? programs.filter(p => p.grantId === grantId) : programs;

  const formTotal      = computeTotal(form.budgetItems);
  const formTotalUSD   = formTotal * (form.exchangeRate || rate);
  const formSubTotal   = (form.subPrograms || []).reduce((s, sp) => s + computeTotal(sp.budgetItems || []), 0);
  const formGrandTotal = formTotal + formSubTotal;
  const formGrandUSD   = formGrandTotal * (form.exchangeRate || rate);

  return (
    <div>
      {toast && <div style={{ position: "fixed", bottom: 24, right: 24, background: "#2d7a4f", color: "#fff", padding: "10px 18px", borderRadius: 8, fontSize: 13, fontWeight: 500, zIndex: 9999 }}>✓ {toast}</div>}
      <div className="page-title">Programs</div>

      {/* Legacy unassigned banner */}
      {grantId && unassignedCount > 0 && !bannerDismissed && (
        <div style={{ background: "#fff8e1", border: "1px solid #ffe082", borderRadius: 8, padding: "10px 14px", fontSize: 13, marginBottom: 16, display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
          <span><strong>{unassignedCount}</strong> program{unassignedCount !== 1 ? "s have" : " has"} no grant assigned — they are hidden while a grant is selected.</span>
          <div style={{ display: "flex", gap: 8 }}>
            {canEdit && <button className="btn btn-sm btn-primary" onClick={assignUnassigned}>Assign {unassignedCount} to this grant</button>}
            <button className="btn btn-sm" onClick={() => setBannerDismissed(true)}>Dismiss</button>
          </div>
        </div>
      )}

      {canEdit && (
        <div style={{ display: "flex", justifyContent: "flex-end", gap: 10, marginBottom: 16, flexWrap: "wrap" }}>
          <a className="btn btn-sm" href={`${process.env.PUBLIC_URL}/templates/wkk-budget-template.xlsx`} download>Download budget template</a>
          {canImport && <button className="btn" onClick={() => setShowImport(true)}>Import budget (Excel)</button>}
          {programs.length === 0 && <button className="btn" onClick={seedDefaults}>Add default programs</button>}
          <button className="btn btn-primary" onClick={openCreate}>+ New program</button>
        </div>
      )}

      {showImport && (
        <ImportBudgetModal
          profile={profile}
          grantId={grantId}
          settings={settings}
          conversionRate={rate}
          onClose={() => setShowImport(false)}
          onImported={({ programs: pCount, personnel: perCount, opsEntries: opsCount }) => {
            showToast(`Imported ${pCount} program(s), ${perCount} personnel role(s), ${opsCount} operational entr${opsCount === 1 ? "y" : "ies"}.`);
          }}
        />
      )}

      {showForm && (
        <div className="panel" style={{ border: "2px solid #4a9e6b", marginBottom: 20 }}>
          <div className="panel-title">{editId ? "Edit program" : "New program"}</div>

          {/* Basic info */}
          <div className="form-grid">
            <div className="field"><label>Program name <span className="req">★</span></label><input value={form.name} onChange={e => setF("name", e.target.value)} placeholder="e.g. Wiki Women" /></div>
            <div className="field"><label>Category</label>
              <select value={form.category} onChange={e => setF("category", e.target.value)}>
                {PROGRAM_CATEGORIES.map(c => <option key={c}>{c}</option>)}
              </select>
            </div>
            <div className="field">
              <label>Planned sessions</label>
              <input type="number" min="1" value={form.plannedSessions} onChange={e => setF("plannedSessions", Number(e.target.value))} disabled={(form.subPrograms || []).length > 0} />
              {(form.subPrograms || []).length > 0 && (
                <div style={{ fontSize: 11, color: "#888", marginTop: 3 }}>Overridden to {form.subPrograms.length} by the sub-programs defined below.</div>
              )}
            </div>
            <div className="field"><label>Exchange rate (USD per TZS)</label>
              <input type="number" step="0.000001" value={form.exchangeRate || rate} onChange={e => setF("exchangeRate", Number(e.target.value) || rate)} placeholder={rate} />
            </div>
            <div className="field"><label>Colour</label>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap", paddingTop: 4 }}>
                {PROGRAM_COLORS.map(c => (
                  <div key={c} onClick={() => setF("color", c)} style={{ width: 24, height: 24, borderRadius: "50%", background: c, cursor: "pointer", border: form.color === c ? "3px solid #1c2b1e" : "2px solid transparent" }} />
                ))}
              </div>
            </div>
          </div>
          <div className="field"><label>Description</label><RichTextEditor value={form.description} onChange={v => setF("description", v)} placeholder="Describe the goals and approach of this program" rows={2} /></div>

          {/* Budget line items */}
          <div style={{ marginTop: 18 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
              <div style={{ fontWeight: 700, fontSize: 13 }}>Budget breakdown</div>
              <button className="btn btn-sm btn-primary" onClick={addItem}>+ Add line item</button>
            </div>

            {form.budgetItems.length === 0 ? (
              <div className="empty" style={{ padding: "12px 0" }}>No budget items yet. Click "+ Add line item" to start.</div>
            ) : (
              <div style={{ overflowX: "auto" }}>
                <table>
                  <thead>
                    <tr>
                      <th>Description</th>
                      <th>Note</th>
                      <th style={{ textAlign: "right" }}>Unit cost (TZS)</th>
                      <th style={{ textAlign: "center" }}>Qty</th>
                      <th style={{ textAlign: "right" }}>Total (TZS)</th>
                      <th>Expense type</th>
                      <th style={{ textAlign: "right" }}>USD</th>
                      <th></th>
                    </tr>
                  </thead>
                  <tbody>
                    {form.budgetItems.map((item, i) => {
                      const total = (Number(item.unitCost) || 0) * (Number(item.quantity) || 1);
                      const usd   = total * (form.exchangeRate || rate);
                      return (
                        <tr key={item.id}>
                          <td><input value={item.description} onChange={e => setItem(i, "description", e.target.value)} placeholder="e.g. Food and drinks" style={{ minWidth: 160 }} /></td>
                          <td><input value={item.note} onChange={e => setItem(i, "note", e.target.value)} placeholder="e.g. Refreshments for participants" style={{ minWidth: 180 }} /></td>
                          <td><input type="number" min="0" value={item.unitCost || ""} onChange={e => setItem(i, "unitCost", Number(e.target.value) || 0)} style={{ width: 110, textAlign: "right" }} /></td>
                          <td><input type="number" min="1" value={item.quantity || ""} onChange={e => setItem(i, "quantity", Number(e.target.value) || 1)} style={{ width: 60, textAlign: "center" }} /></td>
                          <td style={{ textAlign: "right", fontWeight: 600 }}>{fmt(total)}</td>
                          <td>
                            <select value={item.expenseType} onChange={e => setItem(i, "expenseType", e.target.value)} style={{ minWidth: 140 }}>
                              {EXPENSE_TYPES.map(t => <option key={t}>{t}</option>)}
                            </select>
                          </td>
                          <td style={{ textAlign: "right", color: "#555" }}>{fmtUSD(usd)}</td>
                          <td><button className="btn btn-sm btn-danger" onClick={() => removeItem(i)}>✕</button></td>
                        </tr>
                      );
                    })}
                  </tbody>
                  <tfoot>
                    <tr style={{ fontWeight: 700, background: "#f5f4f0" }}>
                      <td colSpan={4} style={{ textAlign: "right" }}>You wish to be reimbursed in TZS:</td>
                      <td style={{ textAlign: "right", fontSize: 14 }}>{fmt(formTotal)}</td>
                      <td style={{ textAlign: "right", fontSize: 12, color: "#555" }}>USD</td>
                      <td style={{ textAlign: "right", fontSize: 14 }}>{fmtUSD(formTotalUSD)}</td>
                      <td></td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            )}
          </div>

          {/* Sub-programs / Sessions */}
          <div style={{ marginTop: 22, borderTop: "1px solid #e8e8e4", paddingTop: 16 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
              <div>
                <div style={{ fontWeight: 700, fontSize: 13 }}>Sub-programs / Sessions</div>
                <div style={{ fontSize: 11, color: "#888", marginTop: 2 }}>Break the program into sessions, each with its own budget (e.g. Session 1 — Editathon Basics).</div>
              </div>
              <button className="btn btn-sm btn-primary" onClick={addSubProgram}>+ Add session</button>
            </div>
            {(!form.subPrograms || form.subPrograms.length === 0) ? (
              <div className="empty" style={{ padding: "10px 0", fontSize: 12 }}>No sessions yet — click "+ Add session" to define per-session budgets.</div>
            ) : (
              form.subPrograms.map((sp, si) => {
                const spTotal    = computeTotal(sp.budgetItems || []);
                const spTotalUSD = spTotal * (form.exchangeRate || rate);
                return (
                  <div key={sp.id} style={{ border: "1px solid #d8d8d2", borderRadius: 8, padding: 14, marginBottom: 12, background: "#fafaf8" }}>
                    <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 10, flexWrap: "wrap" }}>
                      <span style={{ fontSize: 11, fontWeight: 700, color: "#888", minWidth: 20 }}>#{si + 1}</span>
                      <input
                        value={sp.name}
                        onChange={e => setSubP(si, "name", e.target.value)}
                        placeholder={`Session ${si + 1} name`}
                        style={{ flex: 1, minWidth: 160 }}
                      />
                      <input
                        value={sp.description || ""}
                        onChange={e => setSubP(si, "description", e.target.value)}
                        placeholder="Short description (optional)"
                        style={{ flex: 2, minWidth: 200 }}
                      />
                      <button className="btn btn-sm btn-danger" onClick={() => removeSubProgram(si)}>✕</button>
                    </div>

                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                      <div style={{ fontSize: 12, color: "#666", fontWeight: 600 }}>Budget items</div>
                      <button className="btn btn-sm" onClick={() => addSubItem(si)}>+ Add item</button>
                    </div>
                    {(sp.budgetItems || []).length === 0 ? (
                      <div style={{ fontSize: 12, color: "#aaa", padding: "4px 0" }}>No budget items yet.</div>
                    ) : (
                      <div style={{ overflowX: "auto" }}>
                        <table style={{ fontSize: 12 }}>
                          <thead>
                            <tr>
                              <th>Description</th>
                              <th>Note</th>
                              <th style={{ textAlign: "right" }}>Unit cost (TZS)</th>
                              <th style={{ textAlign: "center" }}>Qty</th>
                              <th style={{ textAlign: "right" }}>Total (TZS)</th>
                              <th>Expense type</th>
                              <th style={{ textAlign: "right" }}>USD</th>
                              <th></th>
                            </tr>
                          </thead>
                          <tbody>
                            {sp.budgetItems.map((item, ii) => {
                              const itemTotal = (Number(item.unitCost) || 0) * (Number(item.quantity) || 1);
                              const itemUSD   = itemTotal * (form.exchangeRate || rate);
                              return (
                                <tr key={item.id}>
                                  <td><input value={item.description} onChange={e => setSubItem(si, ii, "description", e.target.value)} placeholder="e.g. Food and drinks" style={{ minWidth: 140 }} /></td>
                                  <td><input value={item.note} onChange={e => setSubItem(si, ii, "note", e.target.value)} placeholder="e.g. Refreshments" style={{ minWidth: 160 }} /></td>
                                  <td><input type="number" min="0" value={item.unitCost || ""} onChange={e => setSubItem(si, ii, "unitCost", Number(e.target.value) || 0)} style={{ width: 110, textAlign: "right" }} /></td>
                                  <td><input type="number" min="1" value={item.quantity || ""} onChange={e => setSubItem(si, ii, "quantity", Number(e.target.value) || 1)} style={{ width: 60, textAlign: "center" }} /></td>
                                  <td style={{ textAlign: "right", fontWeight: 600 }}>{fmt(itemTotal)}</td>
                                  <td>
                                    <select value={item.expenseType} onChange={e => setSubItem(si, ii, "expenseType", e.target.value)} style={{ minWidth: 130 }}>
                                      {EXPENSE_TYPES.map(t => <option key={t}>{t}</option>)}
                                    </select>
                                  </td>
                                  <td style={{ textAlign: "right", color: "#555" }}>{fmtUSD(itemUSD)}</td>
                                  <td><button className="btn btn-sm btn-danger" onClick={() => removeSubItem(si, ii)}>✕</button></td>
                                </tr>
                              );
                            })}
                          </tbody>
                          <tfoot>
                            <tr style={{ fontWeight: 700, background: "#f0f0eb" }}>
                              <td colSpan={4} style={{ textAlign: "right", fontSize: 12 }}>Session total:</td>
                              <td style={{ textAlign: "right" }}>{fmt(spTotal)} TZS</td>
                              <td style={{ textAlign: "right", fontSize: 12, color: "#555" }}>USD</td>
                              <td style={{ textAlign: "right" }}>{fmtUSD(spTotalUSD)}</td>
                              <td></td>
                            </tr>
                          </tfoot>
                        </table>
                      </div>
                    )}
                  </div>
                );
              })
            )}
          </div>

          {/* Grand total */}
          {(form.subPrograms || []).length > 0 && (
            <div style={{ background: "#f0f7f3", border: "1px solid #b8ddc8", borderRadius: 8, padding: "10px 16px", marginTop: 10, display: "flex", justifyContent: "flex-end", gap: 24, fontSize: 13 }}>
              <span style={{ color: "#666" }}>Grand total (program + all sessions):</span>
              <span style={{ fontWeight: 700, color: "#2d7a4f" }}>{fmt(formGrandTotal)} TZS</span>
              <span style={{ fontWeight: 700, color: "#2d7a4f" }}>{fmtUSD(formGrandUSD)}</span>
            </div>
          )}

          <div className="btn-row" style={{ marginTop: 16 }}>
            <button className="btn btn-primary" onClick={save}>Save program</button>
            <button className="btn" onClick={() => setShowForm(false)}>Cancel</button>
          </div>
        </div>
      )}

      {visiblePrograms.length === 0 ? (
        <div className="panel"><div className="empty">No programs yet. Add the default program areas or create a custom one.</div></div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          {visiblePrograms.map(p => {
            const s        = statsFor(p.id);
            const total    = p.plannedBudget || computeTotal(p.budgetItems || []);
            const isExp    = expanded === p.id;
            const pRate    = p.exchangeRate || rate;
            const plannedSess = effectivePlannedSessions(p);
            return (
              <div key={p.id} className="panel" style={{ borderTop: `4px solid ${p.color || "#4a9e6b"}` }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                  <div style={{ flex: 1 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 2, flexWrap: "wrap" }}>
                      <span style={{ fontWeight: 700, fontSize: 15 }}>{p.name}</span>
                      {(() => {
                        const s = STATUS_BADGE[p.status] || STATUS_BADGE.draft;
                        if (p.status === "approved") return <span style={{ fontSize: 10, fontWeight: 700, color: s.color, background: s.bg, border: `1px solid ${s.color}33`, borderRadius: 5, padding: "2px 8px" }}>{s.label}</span>;
                        if (p.status === "submitted") return <span style={{ fontSize: 10, fontWeight: 700, color: s.color, background: s.bg, border: `1px solid ${s.color}33`, borderRadius: 5, padding: "2px 8px" }}>{s.label}</span>;
                        return null; // don't show "Draft" badge to keep cards clean
                      })()}
                    </div>
                    <div style={{ fontSize: 11, color: p.color || "#4a9e6b", fontWeight: 600, marginBottom: 4 }}>{p.category}</div>
                    {p.description && <div style={{ fontSize: 12, color: "#666", marginBottom: 4 }} dangerouslySetInnerHTML={{ __html: renderHtml(p.description) }} />}
                    {p.requestedBudgetUSD > 0 && !hasBudget(p) && (
                      <div style={{ fontSize: 12, color: "#d97706", background: "#fff8e1", border: "1px solid #ffe082", borderRadius: 5, padding: "4px 10px", marginBottom: 4, display: "inline-block" }}>
                        Requested budget (from import): {fmtUSD(p.requestedBudgetUSD)} ({fmt(p.requestedBudgetTZS)} TZS) total
                        {p.requestedPerSessionTZS > 0 && ` — ${fmtUSD(p.requestedPerSessionUSD)} (${fmt(p.requestedPerSessionTZS)} TZS) per session`}
                        . Add the budget line item below to confirm it.
                      </div>
                    )}
                    {p.rejectionComment && (
                      <div style={{ fontSize: 12, color: "#c0392b", background: "#fdf0ee", border: "1px solid #f5c6c0", borderRadius: 5, padding: "4px 10px", marginBottom: 4 }}>
                        Returned: {p.rejectionComment}
                      </div>
                    )}
                    {canEdit && isDraft(p) && !hasBudget(p) && !(p.requestedBudgetUSD > 0) && (
                      <div style={{ fontSize: 12, color: "#888", background: "#f5f4f0", border: "1px solid #e8e8e4", borderRadius: 5, padding: "4px 10px", marginBottom: 4, display: "inline-block" }}>
                        No budget yet — this program can't be submitted until you add at least one budget line item, either directly on the program or inside one of its sessions. Click <strong>Edit</strong> to add one.
                      </div>
                    )}
                    {p.status === "approved" && (
                      <div style={{ fontSize: 11, color: "#2d7a4f" }}>
                        Approved by {p.approvedBy} · {p.approvedAt ? new Date(p.approvedAt).toLocaleDateString("en-GB") : ""}
                        {!isAdmin && <span style={{ marginLeft: 8, color: "#888" }}>budget locked</span>}
                      </div>
                    )}
                  </div>
                  <div style={{ display: "flex", gap: 6, flexShrink: 0, marginLeft: 12, flexWrap: "wrap" }}>
                    {(hasBudget(p) || activities.some(a => a.programId === p.id)) && (
                      <button className="btn btn-sm" onClick={() => setExpanded(isExp ? null : p.id)}>
                        {isExp ? "Hide budget" : "View budget"}
                      </button>
                    )}
                    {/* Submit for approval — draft (or no status) programs with a budget, whether
                        defined at the program level or entirely through sub-program sessions */}
                    {canEdit && (!p.status || p.status === "draft") && hasBudget(p) && (
                      <button className="btn btn-sm btn-primary" onClick={() => submit(p)}>Submit for approval</button>
                    )}
                    {canEditProgram(p) && <button className="btn btn-sm" onClick={() => openEdit(p)}>Edit</button>}
                    {canEditProgram(p) && (!p.status || p.status === "draft") && <button className="btn btn-sm btn-danger" onClick={() => del(p)}>✕</button>}
                  </div>
                </div>

                {/* Stats row */}
                <div style={{ display: "grid", gridTemplateColumns: "repeat(5, 1fr)", gap: 10, borderTop: "1px solid #f0f0ec", paddingTop: 10, marginTop: 6 }}>
                  {[
                    { label: "Sessions",       value: `${s.sessions} / ${plannedSess}` },
                    { label: "Budget (TZS)",   value: total ? fmt(total) : "" },
                    { label: "Participants",   value: s.participants },
                    { label: "Women",          value: s.women },
                    { label: "New editors",    value: s.newEditors },
                  ].map(({ label, value }) => (
                    <div key={label}>
                      <div style={{ fontSize: 10, color: "#888", textTransform: "uppercase", letterSpacing: "0.05em" }}>{label}</div>
                      <div style={{ fontSize: 15, fontWeight: 700, color: p.color || "#2d7a4f" }}>{value}</div>
                    </div>
                  ))}
                </div>

                {/* Session progress bar */}
                <div style={{ marginTop: 10 }}>
                  <div style={{ background: "#e8e8e4", borderRadius: 4, height: 5 }}>
                    <div style={{ width: `${Math.min(100, Math.round((s.sessions / plannedSess) * 100))}%`, height: 5, borderRadius: 4, background: p.color || "#4a9e6b" }} />
                  </div>
                  <div style={{ fontSize: 10, color: "#aaa", marginTop: 3 }}>
                    {Math.round((s.sessions / plannedSess) * 100)}% of planned sessions complete
                    {(p.subPrograms || []).length > 0 && <span style={{ marginLeft: 4 }}>(based on the {p.subPrograms.length} sub-programs defined)</span>}
                  </div>
                </div>

                {/* Budget breakdown table */}
                {isExp && p.budgetItems?.length > 0 && (
                  <div style={{ marginTop: 16, borderTop: "1px solid #e8e8e4", paddingTop: 14 }}>
                    <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 8, textTransform: "uppercase", letterSpacing: "0.5px", color: "#555" }}>Budget breakdown</div>
                    <div style={{ overflowX: "auto" }}>
                      <table style={{ fontSize: 12 }}>
                        <thead>
                          <tr>
                            <th>Description</th>
                            <th>Note</th>
                            <th style={{ textAlign: "right" }}>Unit cost (TZS)</th>
                            <th style={{ textAlign: "right" }}>Total (TZS)</th>
                            <th>Expense type</th>
                            <th style={{ textAlign: "center" }}>Qty</th>
                            <th style={{ textAlign: "right" }}>Exchange rate</th>
                            <th style={{ textAlign: "right" }}>USD</th>
                          </tr>
                        </thead>
                        <tbody>
                          {p.budgetItems.map((item, i) => {
                            const total = (Number(item.unitCost) || 0) * (Number(item.quantity) || 1);
                            const usd   = total * (item.exchangeRate || pRate);
                            return (
                              <tr key={i}>
                                <td style={{ fontWeight: 500 }}>{item.description || ""}</td>
                                <td style={{ color: "#555" }}>{item.note || ""}</td>
                                <td style={{ textAlign: "right" }}>{fmt(item.unitCost)}</td>
                                <td style={{ textAlign: "right", fontWeight: 600 }}>{fmt(total)}</td>
                                <td>{item.expenseType}</td>
                                <td style={{ textAlign: "center" }}>{item.quantity}</td>
                                <td style={{ textAlign: "right", color: "#888" }}>{(item.exchangeRate || pRate).toFixed(7)}</td>
                                <td style={{ textAlign: "right", fontWeight: 600 }}>{fmtUSD(usd)}</td>
                              </tr>
                            );
                          })}
                        </tbody>
                        <tfoot>
                          <tr style={{ fontWeight: 700, background: "#f5f4f0" }}>
                            <td colSpan={3} style={{ textAlign: "right" }}>You wish to be reimbursed in TZS:</td>
                            <td style={{ textAlign: "right" }}>{fmt(total)}</td>
                            <td style={{ textAlign: "right" }}>USD</td>
                            <td></td>
                            <td></td>
                            <td style={{ textAlign: "right" }}>{fmtUSD(total * pRate)}</td>
                          </tr>
                        </tfoot>
                      </table>
                    </div>
                  </div>
                )}

                {/* Sub-programs breakdown */}
                {isExp && (p.subPrograms || []).length > 0 && (
                  <div style={{ marginTop: 16, borderTop: "1px solid #e8e8e4", paddingTop: 14 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
                      <div style={{ fontWeight: 700, fontSize: 12, textTransform: "uppercase", letterSpacing: "0.5px", color: "#555" }}>Sessions / Sub-programs</div>
                      <div style={{ fontSize: 11, color: "#888" }}>
                        {p.subPrograms.filter(sp => activities.some(a => a.programId === p.id && a.subProgramId === sp.id)).length} of {p.subPrograms.length} logged
                      </div>
                    </div>
                    {p.subPrograms.map((sp, si) => {
                      const spTotal    = computeTotal(sp.budgetItems || []);
                      const spTotalUSD = spTotal * pRate;
                      const spActivities = activities.filter(a => a.programId === p.id && a.subProgramId === sp.id);
                      const isLogged = spActivities.length > 0;
                      // Spend attribution: prefer entries tagged directly with this
                      // sub-program; fall back to entries linked via an Activity that
                      // is itself tagged to this sub-program (older entries created
                      // before subProgramId existed on budget entries).
                      const spActivityIds = new Set(spActivities.map(a => a.id));
                      const spSpent = budgetEntries
                        .filter(e => e.programId === p.id && e.status === "approved")
                        .filter(e => e.subProgramId ? e.subProgramId === sp.id : spActivityIds.has(e.activityId))
                        .reduce((s, e) => s + (e.amount || 0), 0);
                      const spRemaining  = spTotal - spSpent;
                      const spOverBudget = spRemaining < 0;
                      const spStatus     = sp.status || "draft";
                      const spBadge      = STATUS_BADGE[spStatus];
                      const spIsDraft    = spStatus === "draft";
                      return (
                        <div key={sp.id || si} style={{ marginBottom: 14, paddingBottom: 14, borderBottom: "1px solid #f0f0ea" }}>
                          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 4, flexWrap: "wrap", gap: 8 }}>
                            <div style={{ fontWeight: 700, fontSize: 13, display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                              <span style={{ color: "#aaa" }}>#{si + 1}</span>
                              {sp.name || `Session ${si + 1}`}
                              {isLogged ? (
                                <span style={{ fontSize: 10, fontWeight: 700, color: "#2d7a4f", background: "#e6f4ec", borderRadius: 5, padding: "2px 8px" }}>✓ Logged ({spActivities.length})</span>
                              ) : (
                                <span style={{ fontSize: 10, fontWeight: 700, color: "#d97706", background: "#fff8e1", borderRadius: 5, padding: "2px 8px" }}>Not logged yet</span>
                              )}
                              {spBadge && (
                                <span style={{ fontSize: 10, fontWeight: 700, color: spBadge.color, background: spBadge.bg, border: `1px solid ${spBadge.color}33`, borderRadius: 5, padding: "2px 8px" }}>
                                  {spStatus === "approved" ? "Session approved" : spBadge.label}
                                </span>
                              )}
                            </div>
                            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                              <div style={{ fontWeight: 700, fontSize: 13, color: p.color || "#2d7a4f" }}>
                                {fmt(spTotal)} TZS <span style={{ fontSize: 11, color: "#888", fontWeight: 400 }}>({fmtUSD(spTotalUSD)})</span>
                              </div>
                              {canEdit && spIsDraft && (sp.budgetItems || []).length > 0 && (
                                <button className="btn btn-sm btn-primary" onClick={() => submitSession(p, sp)}>Submit for approval</button>
                              )}
                            </div>
                          </div>
                          {sp.rejectionComment && (
                            <div style={{ fontSize: 11, color: "#c0392b", background: "#fdf0ee", border: "1px solid #f5c6c0", borderRadius: 5, padding: "4px 10px", marginBottom: 6 }}>
                              Returned: {sp.rejectionComment}
                            </div>
                          )}
                          {spStatus === "approved" && (
                            <div style={{ fontSize: 11, color: "#2d7a4f", marginBottom: 6 }}>
                              Approved by {sp.approvedBy} · {sp.approvedAt ? new Date(sp.approvedAt).toLocaleDateString("en-GB") : ""}
                            </div>
                          )}
                          {isLogged && (
                            <div style={{ fontSize: 11, color: "#555", marginBottom: 6 }}>
                              {spActivities.map(a => a.date).sort().join(", ")}
                            </div>
                          )}
                          {spTotal > 0 && (
                            <div style={{ display: "flex", gap: 16, fontSize: 11, marginBottom: 6 }}>
                              <span style={{ color: "#888" }}>Spent: <strong style={{ color: spOverBudget ? "#c0392b" : "#2d7a4f" }}>TZS {fmt(spSpent)}</strong></span>
                              <span style={{ color: "#888" }}>Remaining: <strong style={{ color: spOverBudget ? "#c0392b" : "#2d7a4f" }}>TZS {fmt(spRemaining)}</strong>{spOverBudget ? " — over budget" : ""}</span>
                            </div>
                          )}
                          {sp.description && <div style={{ fontSize: 12, color: "#666", marginBottom: 6 }}>{sp.description}</div>}
                          {(sp.budgetItems || []).length > 0 && (
                            <div style={{ overflowX: "auto" }}>
                              <table style={{ fontSize: 12 }}>
                                <thead>
                                  <tr>
                                    <th>Description</th>
                                    <th>Note</th>
                                    <th style={{ textAlign: "right" }}>Unit cost (TZS)</th>
                                    <th style={{ textAlign: "right" }}>Total (TZS)</th>
                                    <th>Expense type</th>
                                    <th style={{ textAlign: "center" }}>Qty</th>
                                    <th style={{ textAlign: "right" }}>USD</th>
                                  </tr>
                                </thead>
                                <tbody>
                                  {sp.budgetItems.map((item, ii) => {
                                    const itemTotal = (Number(item.unitCost) || 0) * (Number(item.quantity) || 1);
                                    const itemUSD   = itemTotal * (item.exchangeRate || pRate);
                                    return (
                                      <tr key={ii}>
                                        <td style={{ fontWeight: 500 }}>{item.description || ""}</td>
                                        <td style={{ color: "#555" }}>{item.note || ""}</td>
                                        <td style={{ textAlign: "right" }}>{fmt(item.unitCost)}</td>
                                        <td style={{ textAlign: "right", fontWeight: 600 }}>{fmt(itemTotal)}</td>
                                        <td>{item.expenseType}</td>
                                        <td style={{ textAlign: "center" }}>{item.quantity}</td>
                                        <td style={{ textAlign: "right", fontWeight: 600 }}>{fmtUSD(itemUSD)}</td>
                                      </tr>
                                    );
                                  })}
                                </tbody>
                              </table>
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                )}

                {/* Spending by session — only for programs that don't break their budget
                    into sub-programs; those get per-session Spent/Remaining above instead. */}
                {isExp && (p.subPrograms || []).length === 0 && (() => {
                  const sessions = activities.filter(a => a.programId === p.id).sort((a, b) => (a.date || "").localeCompare(b.date || ""));
                  if (sessions.length === 0) return null;
                  const fallbackPlan = (p.plannedBudget || computeTotal(p.budgetItems || [])) / (p.plannedSessions || 1);
                  const sessionPlanned = p.requestedPerSessionTZS || fallbackPlan;
                  return (
                    <div style={{ marginTop: 16, borderTop: "1px solid #e8e8e4", paddingTop: 14 }}>
                      <div style={{ fontWeight: 700, fontSize: 12, marginBottom: 8, textTransform: "uppercase", letterSpacing: "0.5px", color: "#555" }}>Spending by session</div>
                      <div style={{ overflowX: "auto" }}>
                        <table style={{ fontSize: 12 }}>
                          <thead><tr><th>Session</th><th style={{ textAlign: "right" }}>Planned (TZS)</th><th style={{ textAlign: "right" }}>Spent (TZS)</th><th style={{ textAlign: "right" }}>Remaining</th></tr></thead>
                          <tbody>
                            {sessions.map(a => {
                              const spent = budgetEntries.filter(e => e.activityId === a.id && e.status === "approved").reduce((s, e) => s + (e.amount || 0), 0);
                              const remaining = sessionPlanned - spent;
                              return (
                                <tr key={a.id}>
                                  <td>{a.date} — {a.name}</td>
                                  <td style={{ textAlign: "right" }}>{fmt(sessionPlanned)}</td>
                                  <td style={{ textAlign: "right", fontWeight: 600 }}>{fmt(spent)}</td>
                                  <td style={{ textAlign: "right", color: remaining < 0 ? "#c0392b" : "#2d7a4f" }}>{fmt(remaining)}</td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  );
                })()}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
